-- =============================================================================
-- Script de Carga Completa de Teste - Sistema Gerenciador de Cesta Básica
-- Banco: PostgreSQL (cestabasica_teste)
-- Origem: 1.060 funcionários de funcionarios.sql + dados complementares
-- =============================================================================
BEGIN;

TRUNCATE TABLE retiradas, notificacoes, funcionarios, cestas, historico_importacoes, configuracao_sistema, usuarios RESTART IDENTITY CASCADE;

-- 1. Configurações do Sistema
VALUES (1, TRUE, FALSE, TRUE, 60, TRUE, 'Diario', TRUE, TRUE);

-- 2. Usuários de Acesso (Senhas com hash BCrypt)
-- Admin: admin@cestabasica.com / Admin@123
-- Operador: operador@cestabasica.com / Operador@123
-- Operador 2: triagem@cestabasica.com / Operador@123
-- Inativo: inativo@cestabasica.com / Operador@123

-- 3. Lotes de Cestas Básicas (5 encerrados + 1 lote vigente Novembro/2026)

-- 4. Funcionários (1.060 registros importados de funcionarios.sql com dados faltantes preenchidos)

-- 5. Retiradas (5192 entregas históricas e do mês atual)

-- 6. Notificações (120 envios registrados)

-- 7. Histórico de Importações

-- 8. Ajuste das sequences de IDENTITY do PostgreSQL
SELECT setval(pg_get_serial_sequence('configuracao_sistema', 'Id'), COALESCE((SELECT MAX("Id") FROM configuracao_sistema), 1), true);
SELECT setval(pg_get_serial_sequence('usuarios', 'Id'), COALESCE((SELECT MAX("Id") FROM usuarios), 1), true);
SELECT setval(pg_get_serial_sequence('cestas', 'Id'), COALESCE((SELECT MAX("Id") FROM cestas), 1), true);
SELECT setval(pg_get_serial_sequence('funcionarios', 'Id'), COALESCE((SELECT MAX("Id") FROM funcionarios), 1), true);
SELECT setval(pg_get_serial_sequence('retiradas', 'Id'), COALESCE((SELECT MAX("Id") FROM retiradas), 1), true);
SELECT setval(pg_get_serial_sequence('notificacoes', 'Id'), COALESCE((SELECT MAX("Id") FROM notificacoes), 1), true);
SELECT setval(pg_get_serial_sequence('historico_importacoes', 'Id'), COALESCE((SELECT MAX("Id") FROM historico_importacoes), 1), true);

COMMIT;
